"""Render the independent El Budare's restaurant website from the transcribed menu."""
from pathlib import Path
from html import escape
from collections import Counter
import json
base=Path(__file__).resolve().parents[1]
r=base/'el-budares' if (base/'el-budares').is_dir() else base
data=json.loads((r/'assets/menu.json').read_text())
items=data['items'];counts=Counter(i['category'] for i in items)
e=escape
money=lambda cents:f'{cents/100:.2f}'.replace('.',',')+' €'
def photo(item,cls=''):
 return f'<div class="food-photo tile-{item["tile"]} {cls}" style="background-image:url(\'assets/{item["image"]}.webp\')" role="img" aria-label="Fotografía ilustrativa de {e(item["name"])}"></div>'
def addbutton(item):
 return f'<button class="add-button" data-add="{item["id"]}" aria-label="Añadir {e(item["name"])} a mi selección">+</button>'
menu=''
for item in items:
 star='<sup aria-label="precio orientativo">*</sup>' if item['estimated'] else ''
 menu+=f'''<article class="menu-card" data-category="{e(item['category'])}" data-item="{item['id']}"><button class="menu-image-button" data-details="{item['id']}" aria-label="Ver {e(item['name'])}">{photo(item)}<span class="image-label">{e(item['category'])}</span></button><div class="menu-content"><h3>{e(item['name'])}</h3><p>{e(item['description'])}</p><div class="menu-card-actions"><span class="price">{money(item['price'])}{star}</span>{addbutton(item)}</div></div></article>'''
featured=''
for item in [i for i in items if i['featured']]:
 featured+=f'''<article class="feature-card">{photo(item)}<div class="feature-body"><span class="card-category">{e(item['category'])}</span><h3>{e(item['name'])}</h3><div class="feature-bottom"><span class="price">{money(item['price'])}</span><button class="button" data-details="{item['id']}">Lo quiero <span aria-hidden="true">↗</span></button></div></div></article>'''
filters=f'<button class="filter" data-filter="all" aria-pressed="true">Todo<span class="number-badge">{len(items)}</span></button>'
for name,count in counts.items():filters+=f'<button class="filter" data-filter="{e(name)}" aria-pressed="false">{e(name)}<span class="number-badge">{count}</span></button>'
links=lambda label,url:f'<a class="button ghost" href="{e(url)}" target="_blank" rel="noopener noreferrer">{label} <span aria-hidden="true">↗</span></a>'
providers=f'''<a class="delivery-option" href="{e(data['glovo'])}" target="_blank" rel="noopener noreferrer"><span><h3>Glovo</h3><p>Consulta carta, entrega y disponibilidad.</p></span><span class="provider-arrow" aria-hidden="true">↗</span></a><a class="delivery-option" href="{e(data['uber'])}" target="_blank" rel="noopener noreferrer"><span><h3>Uber Eats</h3><p>Consulta opciones de recogida en la plataforma.</p></span><span class="provider-arrow" aria-hidden="true">↗</span></a>'''
reviews=''
for i,review in enumerate(data['reviews']):
 if review.get('verifiedText') and review.get('text'):
  reviews+=f'<article class="review-card motion-item"><blockquote>{e(review["text"])}</blockquote><cite>{e(review.get("author","Autor en Google"))}</cite><a href="{e(review["url"])}" target="_blank" rel="noopener noreferrer">Leer la reseña original ↗</a></article>'
 else:
  reviews+=f'''<a class="review-card review-reference motion-item" href="{e(review['url'])}" target="_blank" rel="noopener noreferrer" aria-label="Abrir reseña de Google {i+1}"><span class="eyebrow">Google Maps / {i+1:02d}</span><h3>La experiencia,<br>en primera persona.</h3><span class="text-link">Leer la reseña original ↗</span></a>'''
brand='<span class="wordmark"><span class="brand-icon" aria-hidden="true">B</span><span>El Budare’s<small>Bar café · Bilbao</small></span></span>'
html=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#260212"><meta name="robots" content="noindex,nofollow"><meta name="description" content="El Budare’s en Bilbao: cachapas, empanadas, hamburguesas, pepitos y desayuno criollo. Explora la carta y pide a través de Glovo o Uber Eats."><title>El Budare’s · Sabor sin freno · Bilbao</title><link rel="preload" href="assets/fonts/display.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="assets/budares.css"><script type="module" src="assets/budares.js"></script></head><body><a class="skip" href="#contenido">Saltar al contenido</a><div class="topbar">Bilbao, con sabor venezolano. &nbsp; ◂ &nbsp; El Budare’s &nbsp; ▸ &nbsp; Así de claro.</div><header class="site-header"><nav class="shell nav" aria-label="Navegación principal"><a href="#" aria-label="El Budare’s, inicio">{brand}</a><div class="nav-links" id="navigation"><a href="#carta">La carta</a><a href="#la-casa">La casa</a><a href="#opiniones">Reseñas</a><a href="#encuentranos">Encuéntranos</a></div><div class="nav-actions"><button class="button" data-order>Pide ahora <span aria-hidden="true">↗</span></button><button class="cart-trigger" data-cart aria-label="Abrir mi selección">Mi antojo <span class="cart-count" data-cart-count>0</span></button><button class="mobile-menu" aria-expanded="false" aria-controls="navigation">Menú ☰</button></div></nav></header><main id="contenido"><section class="hero" aria-labelledby="hero-title"><span class="eyebrow">Bar café El Budare’s · Bilbao</span><h1 class="hero-title" id="hero-title"><span>Sabor.</span><span class="parenthesis">(Sin freno.)</span></h1><p class="hero-lead">Cachapas que van con todo. Pepitos con carácter. Antojos que no se negocian. Esto es El Budare’s.</p><div class="hero-actions"><button class="button" data-order>Pide ahora <span aria-hidden="true">↗</span></button><a class="button ghost" href="#carta">Explora la carta <span aria-hidden="true">↓</span></a></div><img class="hero-food food-left" src="assets/hero-burger.webp" alt="Fotografía ilustrativa de una hamburguesa de carne mechada con queso" width="1536" height="1024" fetchpriority="high"><img class="hero-food food-right" src="assets/hero-cachapa.webp" alt="Fotografía ilustrativa de una cachapa con queso y carne" width="1536" height="1024" fetchpriority="high"><div class="food-stamp" aria-hidden="true">Cachapas.<br>Pepitos.<br>Y punto.</div><div class="hero-foot"><a href="#carta"><span class="scroll-arrow" aria-hidden="true">↓</span> Aquí empieza el antojo</a><span>Más sabor. Menos vueltas.<br>Visuales de propuesta.</span></div></section><div class="poster-stripe" aria-hidden="true"><div class="stripe-inner">{''.join(f'<span>{word}</span><i>·</i>' for word in ['Con todo','A lo Budare’s','Bilbao sabe a casa','Sabor sin freno']*3)}</div></div><section class="featured" id="favoritos"><div class="shell"><div class="section-top"><div><span class="eyebrow">Para empezar fuerte</span><h2>Antojos<br>con nombre.</h2></div><div><p class="featured-intro">Una primera vuelta por nuestra carta. El resto te espera un poco más abajo.</p><div class="carousel-controls"><button class="round-button" id="carousel-prev" aria-label="Ver platos anteriores">←</button><button class="round-button" id="carousel-next" aria-label="Ver siguientes platos">→</button></div></div></div><div class="carousel" id="featured-carousel" aria-label="Platos destacados">{featured}</div></div></section><section class="story" id="la-casa"><div class="shell story-grid"><div class="story-photo">{photo(next(i for i in items if i['id']=='cachapa-criolla'))}</div><div class="story-copy motion-item"><span class="eyebrow">La casa</span><h2>Bilbao.<br>Venezuela.<br><em>En la misma mesa.</em></h2><p>Maíz, queso de mano, carne mechada. Una carta que habla claro: sabores venezolanos, bocados generosos y muchas formas de decir «hoy me lo merezco».</p><p>Del desayuno criollo a ese pepito que te llevas en la cabeza todo el día. Elige el tuyo. Nosotros ponemos la carta.</p><a class="button" href="#carta">Vamos a lo importante <span aria-hidden="true">↓</span></a><div class="small-label">El Budare’s · Bar café en Bilbao</div></div></div></section><section class="menu-section" id="carta"><div class="shell"><div class="section-top"><div><span class="eyebrow">La carta</span><h2>Elige<br>tu próximo<br>(antojo).</h2></div><p>{len(items)} propuestas entre cachapas, hamburguesas, pepitos, perros calientes, salchipapas, empanadas, pasteles, platos extra y desayuno criollo.</p></div><div class="menu-tools"><label class="menu-search"><span class="sr-only">Buscar en la carta</span><input type="search" id="menu-search" placeholder="¿Qué te apetece?" aria-label="Buscar platos por nombre o ingredientes"></label><span class="menu-count" id="menu-count" role="status" aria-live="polite">{len(items)} platos</span></div><div class="filters" role="group" aria-label="Filtrar platos por categoría">{filters}</div><div class="menu-grid" id="menu-grid">{menu}</div><p class="menu-empty" id="menu-empty" hidden>No aparece ese antojo. Prueba con otro nombre o vuelve a «Todo».</p><p class="menu-note"><strong>* Precio orientativo de propuesta.</strong> Los importes de huevos rotos y pollo a la canasta no eran legibles en las capturas: se han completado con precios orientativos, pendientes de confirmar. Los demás precios se han transcrito del material facilitado y pueden cambiar. Confirma el precio final, los ingredientes, los alérgenos y la disponibilidad con el restaurante o en la plataforma antes de pedir.</p></div></section><section class="delivery" id="pedidos"><div class="shell"><div class="section-top"><div><span class="eyebrow">El siguiente paso lo eliges tú</span><h2>Hoy se pide<br>(a lo Budare’s).</h2></div><p>El pedido y el pago se completan en la plataforma que elijas. Allí verás precios finales, gastos y disponibilidad.</p></div><div class="delivery-options">{providers}</div></div></section><section class="reviews" id="opiniones"><div class="shell"><div class="section-top"><div><span class="eyebrow">Lo que cuenta quien viene</span><h2>La mesa<br>tiene voz.</h2></div><p>Abre las reseñas originales compartidas de Google Maps. Opiniones en su fuente, sin cambiar una palabra.</p></div><div class="reviews-list">{reviews}</div><p class="fineprint">Los seis enlaces se han facilitado como referencias de reseñas. No se transcriben comentarios, autores ni estrellas sin poder verificarlos.</p></div></section><section class="visit" id="encuentranos"><div class="shell visit-grid"><div class="motion-item"><span class="eyebrow">La próxima parada</span><h2>Tu antojo<br>tiene sitio.</h2><p class="visit-location">Bar café El Budare’s<br>Bilbao</p><p>Consulta en Google Maps la ubicación, el horario actualizado y cómo llegar. La dirección exacta se muestra en la ficha del local.</p><a class="button" href="{e(data['maps'])}" target="_blank" rel="noopener noreferrer">Cómo llegar <span aria-hidden="true">↗</span></a></div><a class="visit-art" href="{e(data['maps'])}" target="_blank" rel="noopener noreferrer" aria-label="Abrir ubicación de El Budare’s en Google Maps"><div class="food-photo location-photo tile-2" style="background-image:url('assets/menu-b.webp')" aria-hidden="true"></div><div class="map-pin" aria-hidden="true"></div><div class="map-card"><strong>El Budare’s</strong>Ver ubicación real en Google Maps ↗</div></a></div></section><section><div class="shell faq"><span class="eyebrow">Sin darle más vueltas</span><h2>Lo que quieres<br>saber.</h2><details><summary>¿Cómo hago un pedido?</summary><p>Pulsa «Pide ahora» y elige Glovo o Uber Eats. Completa allí tu pedido y el pago. La selección de esta web no se transfiere automáticamente a esas plataformas.</p></details><details><summary>¿Puedo preparar mi selección aquí?</summary><p>Sí. Añade platos a «Mi antojo», elige variantes, ajusta cantidades y apunta tus preferencias. Puedes copiar o descargar el resumen. No se envía al restaurante ni reserva productos.</p></details><details><summary>¿Los precios son los mismos en las plataformas?</summary><p>La carta parte de las capturas facilitadas. Los precios, gastos, promociones y disponibilidad de Glovo y Uber Eats pueden ser distintos. Dos precios de esta propuesta se marcan con un asterisco porque no eran legibles.</p></details><details><summary>¿Dónde consulto los alérgenos?</summary><p>Las descripciones no son una declaración completa de ingredientes o alérgenos. Consulta al restaurante o a la plataforma antes de pedir si tienes alergias o intolerancias. No incluyas datos de salud en las notas de esta demo.</p></details><details><summary>¿Cuál es el horario y dónde está el local?</summary><p>Abre la ficha de Google Maps desde «Cómo llegar» para consultar la ubicación exacta y el horario actualizado del local. No se han añadido horarios sin verificar.</p></details></div></section><section class="final-cta"><div class="shell"><span class="eyebrow">La indecisión también da hambre</span><h2>Con todo.<br>(Como te gusta.)</h2><div class="cta-row"><button class="button dark" data-order>Pide ahora <span aria-hidden="true">↗</span></button><button class="button ghost" data-cart>Revisa tu antojo <span data-cart-count>0</span></button></div></div></section></main><footer class="site-footer"><div class="shell"><div class="footer-top"><a href="#" aria-label="El Budare’s, volver al inicio">{brand}</a><div class="footer-links"><a href="#carta">La carta</a><a href="{e(data['maps'])}" target="_blank" rel="noopener noreferrer">Google Maps ↗</a><button class="link-button" data-legal>Sobre esta propuesta</button></div></div><div class="footer-bottom"><p>Propuesta web para Bar café El Budare’s. Fotografías gastronómicas ilustrativas generadas con IA; no son fotografías documentales de sus platos ni garantizan una presentación concreta. Carta y precios sujetos a confirmación.</p><span>© 2026 · Diseño por Tap & Go</span></div></div></footer><button class="floating-cart" data-cart aria-label="Abrir mi selección de platos">Mi antojo <span class="cart-count" data-cart-count>0</span><span aria-hidden="true">↗</span></button><div class="toast" id="toast" role="status" aria-live="polite" hidden></div><dialog class="product-dialog" id="product-dialog" aria-labelledby="product-title"><button class="close-dialog" data-close aria-label="Cerrar plato">×</button><div class="product-detail"><div class="food-photo product-detail-photo" id="detail-photo" role="img" aria-label="Imagen ilustrativa del plato"></div><div class="product-detail-copy"><span class="eyebrow" id="detail-category"></span><h2 id="product-title"></h2><p id="detail-description"></p><span class="price" id="detail-price"></span><label class="field-label" id="detail-option-label" hidden>Elige tu opción<select id="detail-option"></select></label><label class="field-label">Una nota para tu selección<textarea id="detail-note" maxlength="250" placeholder="Por ejemplo: sin cebolla. Confírmalo después en la plataforma."></textarea></label><div class="product-purchase"><div class="quantity-control"><button type="button" id="detail-less" aria-label="Reducir cantidad">−</button><output id="detail-quantity" aria-live="polite">1</output><button type="button" id="detail-more" aria-label="Aumentar cantidad">+</button></div><button class="button" id="detail-add">Añadir a mi antojo <span aria-hidden="true">+</span></button></div><p class="fineprint" id="detail-note-price"></p><p class="fineprint">Selección orientativa. No es un pedido enviado. Confirma ingredientes y alérgenos antes de pedir.</p></div></div></dialog><dialog class="cart-dialog" id="cart-dialog" aria-labelledby="cart-title"><button class="close-dialog" data-close aria-label="Cerrar mi selección">×</button><div class="cart-header"><h2 id="cart-title">Tu antojo.</h2><p>Prepara tu selección y guárdala. Para hacer un pedido real, tendrás que elegir los platos y pagar en Glovo o Uber Eats.</p></div><div class="cart-body"><div id="cart-lines"></div><p class="cart-empty" id="cart-empty">Tu antojo empieza con un plato. Explora la carta y añade lo que te apetezca.</p><div id="cart-summary" hidden><div class="total-row"><span>Subtotal orientativo</span><strong id="cart-total">0,00 €</strong></div><p class="fineprint" id="cart-estimate-note" hidden>Incluye precios marcados como orientativos de propuesta, pendientes de confirmar.</p><div class="cart-disclaimer">No se ha enviado ningún pedido. Esta selección <strong>no se transfiere automáticamente</strong> a las plataformas. Allí debes confirmar productos, variantes, precios, disponibilidad y gastos.</div><div class="cart-checkout">{links('Pedir en Glovo',data['glovo'])}{links('Recoger en Uber Eats',data['uber'])}</div><div class="cart-secondary"><button class="link-button" id="copy-selection">Copiar selección</button><button class="link-button" id="download-selection">Descargar resumen</button><button class="link-button" id="clear-selection">Vaciar selección</button></div><p class="fineprint" id="cart-feedback" role="status"></p></div></div></dialog><dialog class="order-dialog" id="order-dialog" aria-labelledby="order-title"><button class="close-dialog" data-close aria-label="Cerrar opciones de pedido">×</button><span class="eyebrow">El pedido se completa allí</span><h2 id="order-title">Tu antojo.<br>Tu plataforma.</h2><p>Elige dónde quieres pedir. Revisa la carta, la disponibilidad y el importe final antes de confirmar.</p><div class="delivery-options">{providers}</div><p class="fineprint">Los enlaces abren las tiendas facilitadas del restaurante. Si has preparado una selección aquí, deberás añadirla de nuevo en la plataforma.</p></dialog><dialog class="legal-dialog" id="legal-dialog" aria-labelledby="legal-title"><button class="close-dialog" data-close aria-label="Cerrar información">×</button><span class="eyebrow">Información clara</span><h2 id="legal-title">Sobre esta<br>propuesta.</h2><p>Esta web es una propuesta de diseño para Bar café El Budare’s. No procesa pagos ni envía pedidos o reservas al restaurante. Los pedidos reales se completan en los servicios externos enlazados.</p><h3>La carta</h3><p>Se han transcrito 38 referencias de las dos capturas aportadas. Los precios de huevos rotos y pollo a la canasta son orientativos porque no eran legibles y están marcados con *. Los demás importes necesitan confirmación de vigencia. No se incluye una declaración de alérgenos no verificada.</p><h3>Imágenes y reseñas</h3><p>Las imágenes son fotografías ilustrativas generadas con IA y no documentan los platos del local. Las reseñas enlazan a las seis referencias facilitadas por el usuario; no se inventan citas, nombres ni calificaciones.</p><h3>Tu selección y tus datos</h3><p>«Mi antojo» se guarda solo en el almacenamiento local de este navegador para recuperarlo al volver. No se envía a un servidor. Evita incluir datos personales o de salud en las notas. Puedes eliminarlo con «Vaciar selección» o borrando los datos del sitio.</p><h3>Servicios externos</h3><p>Google Maps, Glovo y Uber Eats tienen sus propias condiciones y políticas. Las fuentes y las imágenes de esta propuesta se sirven localmente. No se añaden analítica ni cookies publicitarias propias.</p></dialog></body></html>'''
(r/'index.html').write_text(html)
print('Rendered restaurant home:',len(items),'menu cards;',len(data['reviews']),'review references')
